"""Build the shipped reference catalog. Meanings are original reflection prompts."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
MAJOR = [
    ("Шут", "Новое начало и открытость опыту. Подумай, какой небольшой шаг можно сделать, сохраняя осторожность."),
    ("Маг", "Инициатива и доступные навыки. Заметь, какие ресурсы у тебя уже есть для первого действия."),
    ("Верховная Жрица", "Внимание к внутренним ощущениям и неизвестному. Дай себе время разобраться, прежде чем делать выводы."),
    ("Императрица", "Забота, творчество и рост. Подумай, чему сейчас нужны внимание и поддержка."),
    ("Император", "Границы, порядок и ответственность. Какие понятные правила помогут почувствовать устойчивость?"),
    ("Иерофант", "Традиции, обучение и общие ценности. Какие привычные убеждения помогают, а какие стоит пересмотреть?"),
    ("Влюблённые", "Близость и выбор в согласии с ценностями. Уточни, что важно тебе и что можно обсудить с другим человеком."),
    ("Колесница", "Направление и согласование усилий. Выбери посильную цель и замечай, что находится под твоим контролем."),
    ("Сила", "Мягкая настойчивость и терпение. Как поддержать себя, не прибегая к давлению?"),
    ("Отшельник", "Пауза и самостоятельное осмысление. Найди спокойное время, чтобы услышать собственную позицию."),
    ("Колесо Фортуны", "Перемены и цикличность опыта. Раздели обстоятельства, на которые можно влиять, и то, что приходится принимать."),
    ("Справедливость", "Честность и последствия решений. Посмотри на ситуацию с разных сторон; это не юридическая рекомендация."),
    ("Повешенный", "Пауза и новый взгляд. Иногда полезно временно отложить привычное действие и пересмотреть ожидания."),
    ("Смерть", "Завершение этапа и изменение привычек. Это символ перехода, а не предсказание смерти или несчастья."),
    ("Умеренность", "Баланс и постепенность. Попробуй сочетать разные потребности без крайностей."),
    ("Дьявол", "Привязанности и ограничения. Заметь привычный сценарий и пространство для свободного выбора."),
    ("Башня", "Пересмотр прежних опор. Карта предлагает подумать о поддержке в переменах, но не предсказывает беду."),
    ("Звезда", "Надежда и восстановление доверия к себе. Какое простое действие напомнит о значимых целях?"),
    ("Луна", "Неопределённость и воображение. Отдели наблюдаемые факты от тревожных предположений."),
    ("Солнце", "Ясность и радость. Обрати внимание на то, что даёт энергию и чем хочется поделиться."),
    ("Суд", "Осмысление опыта и обновление. Какие выводы помогут двигаться дальше без самообвинения?"),
    ("Мир", "Завершённость и соединение опыта. Признай сделанное и подумай о следующем небольшом этапе."),
]
RANKS = ["Туз", "Двойка", "Тройка", "Четвёрка", "Пятёрка", "Шестёрка", "Семёрка", "Восьмёрка", "Девятка", "Десятка", "Паж", "Рыцарь", "Королева", "Король"]
SUITS = {
    "wands": ("Жезлов", ["импульс начать", "планирование направления", "расширение горизонтов", "совместная радость и опора", "соперничество и разница интересов", "признание усилий", "защита личной позиции", "темп и движение", "стойкость и необходимость отдыха", "нагрузка и распределение обязанностей", "любознательность и проба нового", "энтузиазм и поспешность", "уверенность и тепло", "ответственность за инициативу"]),
    "cups": ("Кубков", ["открытость чувствам", "взаимность и диалог", "дружба и поддержка", "пауза и неудовлетворённость", "сожаление и сохранившиеся опоры", "воспоминания и доброта", "много желаний и необходимость ясности", "уход от того, что перестало подходить", "удовлетворение и благодарность", "близость и общие ценности", "чуткость и эмоциональное любопытство", "выражение чувств и идеализация", "эмпатия и забота о границах", "устойчивость в общении о чувствах"]),
    "swords": ("Мечей", ["ясность мысли", "трудность выбора и поиск информации", "болезненные чувства и их признание", "отдых и пауза", "цена конфликта", "переход к более спокойным условиям", "осторожность и честность с собой", "ощущение ограниченности и доступные шаги", "тревожные мысли и поиск поддержки", "окончание трудного этапа", "вопросы и проверка фактов", "прямота и риск поспешности", "ясные границы и независимость", "взвешенное рассуждение"]),
    "pentacles": ("Пентаклей", ["практическая возможность", "согласование повседневных задач", "совместная работа и обучение", "устойчивость и излишний контроль", "нехватка поддержки и возможность попросить помощь", "обмен помощью и справедливость", "терпение и оценка вложенных усилий", "практика и внимание к навыку", "самостоятельность и признание труда", "долгосрочные опоры и общие традиции", "ученичество и конкретный план", "последовательность и надёжность", "практическая забота", "ответственное использование ресурсов"]),
}


def main():
    deck = []
    for i, (name, meaning) in enumerate(MAJOR):
        deck.append(dict(id=i, code=f"major_{i:02}", name=name, meaning=meaning, image_path=f"assets/images/major_{i:02}.jpg"))
    for code, (suit, meanings) in SUITS.items():
        for n, (rank, meaning) in enumerate(zip(RANKS, meanings), 1):
            deck.append(dict(id=len(deck), code=f"{code}_{n:02}", name=f"{rank} {suit}", meaning=f"Тема карты — {meaning}. Подумай, как это связано с твоим опытом и какой посильный шаг зависит от тебя. Это повод для размышления, а не предсказание.", image_path=f"assets/images/{code}_{n:02}.jpg"))
    (ROOT / "assets/images").mkdir(parents=True, exist_ok=True)
    (ROOT / "assets/deck.json").write_text(json.dumps(deck, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
